import Link from "next/link";
import { prisma } from "@/core/server/prisma";

export default async function AdminOrdersPage() { const orders = await prisma.order.findMany({ include: { user: { select: { email: true } }, items: { select: { titleSnapshot: true } }, payments: { select: { status: true } }, entitlements: { select: { status: true } } }, orderBy: { createdAt: "desc" }, take: 100 }); return <div><h1 className="text-3xl font-bold">Orders</h1><p className="mt-2 text-slate-600">Webhook-confirmed payment and access state.</p><div className="mt-6 overflow-x-auto rounded-xl border bg-white"><table className="w-full text-left text-sm"><thead><tr className="border-b text-slate-500"><th className="p-3">Number</th><th className="p-3">User</th><th className="p-3">Product</th><th className="p-3">Amount</th><th className="p-3">Provider</th><th className="p-3">Status</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id} className="border-b"><td className="p-3"><Link className="text-blue-700 underline" href={`/admin/billing/orders/${order.id}`}>{order.number}</Link></td><td className="p-3">{order.user.email}</td><td className="p-3">{order.items[0]?.titleSnapshot ?? "—"}</td><td className="p-3">{order.totalAmount / 100} {order.currency}</td><td className="p-3">{order.provider}</td><td className="p-3">{order.status}</td></tr>)}</tbody></table></div></div>; }
